UI_BLOCK = r"""
void draw_features_ui() {
#if MODKIT_HAS_IMGUI
    if (!ImGui::BeginTabBar("tabs", ImGuiTabBarFlags_FittingPolicyScroll)) {
        ImGui::TextUnformatted("no features yet");
        return;
    }
    const char *group = nullptr;
    bool open_tab = false;
    bool any_in_tab = false;
    for (size_t i = 0; i < kN; ++i) {
        const modkit::FeatureDef &f = g_features[i];
        if (!group || strcmp(group, f.group)) {
            if (open_tab) ImGui::EndTabItem();
            group = f.group;
            any_in_tab = false;
            open_tab = ImGui::BeginTabItem(group);
        }
        if (!open_tab) continue;
        any_in_tab = true;
        switch (f.kind) {
        case modkit::F_CONST_RETURN:
        case modkit::F_TOGGLE:
        case modkit::F_HOOK: {
            bool on = g_on[i];
            if (ImGui::Checkbox(f.label, &on)) {
                g_on[i] = on;
                apply(i, on ? (f.def != 0.0 ? f.def : 1.0) : 0.0);
            }
            break;
        }
        case modkit::F_VALUE_SET:
        case modkit::F_FIELD_WRITE:
        case modkit::F_STATIC_WRITE:
        case modkit::F_SLIDER: {
            if (f.hi - f.lo <= 1.0) {          // 0/1 range -> a plain switch, not a drag
                bool on = g_value[i] != 0.0;
                if (ImGui::Checkbox(f.label, &on)) apply(i, on ? (f.def != 0.0 ? f.def : 1.0) : 0.0);
                break;
            }
            float v = (float)g_value[i];
            {
                ImGui::PushID((int)i);
                ImGui::TextUnformatted(f.label);
                ImGui::SameLine();
                ImGui::SetNextItemWidth(180.0f);
                if (ImGui::DragFloat("##v", &v, 1.0f, (float)f.lo, (float)f.hi, "%.0f")) {
                    apply(i, v);
                    g_on[i] = v != 0.0;
                }
                ImGui::PopID();
            }
            break;
        }
        default:
            if (ImGui::Button(f.label)) apply(i, f.def);
            break;
        }
        if (f.flags & modkit::F_NEEDS_INSTANCE) {
            ImGui::SameLine();
            ImGui::TextColored(modkit::instance(f.slot) ? ImVec4(0.3f, 1.f, 0.4f, 1.f)
                                                         : ImVec4(1.f, 0.4f, 0.2f, 1.f),
                               "%s", modkit::instance(f.slot) ? "obj" : "no obj");
        }
    }
    if (open_tab) ImGui::EndTabItem();
    ImGui::EndTabBar();
#else
    // Console-only build: dump the feature list to logcat so `adb shell` still drives it.
    for (size_t i = 0; i < kN; ++i)
        LOGI("[%zu] %-34s %-12s = %g", i, g_features[i].key,
             g_features[i].label, g_value[i]);
#endif
}
"""

CMAKE = """cmake_minimum_required(VERSION 3.22)
project({{project}} CXX)

set(CMAKE_CXX_STANDARD 20)
set(CMAKE_CXX_STANDARD_REQUIRED ON)
set(CMAKE_POSITION_INDEPENDENT_CODE ON)

option(MODKIT_OVERLAY "draw the in-GL menu via the eglSwapBuffers hook" {{overlay}})
option(MODKIT_HAS_IMGUI "third_party/imgui is vendored" {{imgui}})
option(MODKIT_HAVE_DOBBY "link third_party/dobby instead of the built-in inline hooker" {{dobby}})
option(MODKIT_AUTOLOAD "start the runtime from an ELF constructor for DT_NEEDED injection" {{autoload}})

add_library({{project}} SHARED
    jni_main.cpp
    modkit.cpp
    game.cpp)

target_include_directories({{project}} PRIVATE ${CMAKE_CURRENT_SOURCE_DIR})

target_compile_definitions({{project}} PRIVATE
    MODKIT_TARGET_SO="{{target_so}}"
    MODKIT_TAG="{{tag}}"
    MODKIT_OVERLAY=$<BOOL:${MODKIT_OVERLAY}>
    MODKIT_HAS_IMGUI=$<BOOL:${MODKIT_HAS_IMGUI}>
    MODKIT_HAVE_DOBBY=$<BOOL:${MODKIT_HAVE_DOBBY}>
    MODKIT_AUTOLOAD=$<BOOL:${MODKIT_AUTOLOAD}>)

if(MODKIT_OVERLAY)
    target_sources({{project}} PRIVATE overlay.cpp)
endif()

if(MODKIT_HAS_IMGUI)
    file(GLOB IMGUI_SRC
        ${CMAKE_CURRENT_SOURCE_DIR}/../third_party/imgui/*.cpp
        ${CMAKE_CURRENT_SOURCE_DIR}/../third_party/imgui/backends/imgui_impl_opengl3.cpp
        ${CMAKE_CURRENT_SOURCE_DIR}/../third_party/imgui/backends/imgui_impl_opengl3_loader.h)
    target_sources({{project}} PRIVATE ${IMGUI_SRC})
    target_include_directories({{project}} PRIVATE ${CMAKE_CURRENT_SOURCE_DIR}/../third_party/imgui)
endif()

string(APPEND CMAKE_CXX_FLAGS " -D_GNU_SOURCE -Os -fvisibility=hidden -fno-rtti -Wall -Wno-unused-parameter"
       " -ffunction-sections -fdata-sections -fno-strict-aliasing")
string(APPEND CMAKE_SHARED_LINKER_FLAGS
       " -Wl,--gc-sections -Wl,--exclude-libs,ALL -Wl,-z,max-page-size=16384 -Wl,--build-id=sha1")

target_link_libraries({{project}} PRIVATE log android EGL GLESv3)

if(MODKIT_HAVE_DOBBY AND EXISTS ${CMAKE_CURRENT_SOURCE_DIR}/../third_party/dobby/CMakeLists.txt)
    add_subdirectory(${CMAKE_CURRENT_SOURCE_DIR}/../third_party/dobby ${CMAKE_BINARY_DIR}/dobby)
    target_link_libraries({{project}} PRIVATE dobby)
endif()
"""

