MODKIT_JAVA = """package {{package}}.loader;

// Thin JNI facade over lib{{lib}}.so — the whole menu lives in native code.
public final class ModKit {

    private static volatile boolean loaded;

    private ModKit() {}

    public static synchronized void load() {
        if (loaded) return;
        System.loadLibrary("{{lib}}");
        loaded = true;
    }

    public static boolean ready() { return loaded && nativeReady(); }

    public static native void nativeInit();
    public static native boolean nativeReady();
    public static native String nativeStatus();
    public static native void nativeSetFeature(String key, double value);
    public static native double nativeGetFeature(String key);
    public static native void nativePushTouch(int action, float x, float y);
}
"""

LOADER_JAVA = """package {{package}}.loader;

import android.app.Activity;
import android.os.Bundle;
import android.text.InputType;
import android.view.MotionEvent;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;

/**
 * Console for the generated module: pick a feature key, type a value, apply.
 * The real menu is drawn inside the game (overlay.cpp) — this exists so a build
 * without ImGui is still operable, and so offsets can be probed one by one.
 */
public final class LoaderActivity extends Activity {

    private static final String[] KEYS = new String[] {
{{keys}}
    };

    private EditText value;
    private TextView status;

    @Override
    protected void onCreate(Bundle saved) {
        super.onCreate(saved);
        ModKit.load();
        ModKit.nativeInit();

        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        int pad = (int) (16 * getResources().getDisplayMetrics().density);
        root.setPadding(pad, pad, pad, pad);

        status = new TextView(this);
        status.setTextIsSelectable(true);
        root.addView(status);

        Button refresh = new Button(this);
        refresh.setText("refresh status");
        refresh.setOnClickListener(v -> status.setText(ModKit.nativeStatus()));
        root.addView(refresh);

        value = new EditText(this);
        value.setInputType(InputType.TYPE_CLASS_NUMBER | InputType.TYPE_NUMBER_FLAG_DECIMAL
                | InputType.TYPE_NUMBER_FLAG_SIGNED);
        value.setText("1");
        root.addView(value);

        for (String key : KEYS) {
            Button b = new Button(this);
            b.setAllCaps(false);
            b.setText(key);
            b.setOnClickListener(v -> {
                double d = parse(value.getText().toString());
                ModKit.nativeSetFeature(key, d);
                status.setText("set " + key + " = " + d + "\\n" + ModKit.nativeStatus());
            });
            b.setOnLongClickListener(v -> {
                value.setText(String.valueOf(ModKit.nativeGetFeature(key)));
                return true;
            });
            root.addView(b);
        }

        ScrollView sc = new ScrollView(this);
        sc.addView(root);
        setContentView(sc);
        status.setText(ModKit.nativeStatus());
    }

    @Override
    public boolean dispatchTouchEvent(MotionEvent ev) {
        // forwards to the in-game overlay when it runs on top of this console
        ModKit.nativePushTouch(ev.getActionMasked(), ev.getX(), ev.getY());
        return super.dispatchTouchEvent(ev);
    }

    private static double parse(String s) {
        try {
            return Double.parseDouble(s.trim());
        } catch (RuntimeException e) {
            return 1.0;
        }
    }
}
"""

BUILD_SH = """#!/usr/bin/env bash
# Standalone NDK build, no Gradle. Needs $ANDROID_NDK or any ndk/* under $ANDROID_HOME.
set -euo pipefail

ABI="${ABI:-arm64-v8a}"
API="${API:-26}"
NDK="${ANDROID_NDK:-$(ls -d "${ANDROID_HOME:-$HOME/Android/Sdk}"/ndk/* 2>/dev/null | sort -V | tail -1)}"
[ -d "$NDK" ] || { echo "NDK not found: set ANDROID_NDK" >&2; exit 1; }

case "$(uname -s)" in
  Linux)  HOST=linux-x86_64 ;;
  Darwin) HOST=darwin-x86_64 ;;
  *)      HOST=windows-x86_64 ;;
esac

SRC="$(cd "$(dirname "$0")" && pwd)"
OUT="$SRC/build/$ABI"

cmake -S "$SRC/app/src/main/cpp" -B "$OUT" -G Ninja \\
  -DCMAKE_TOOLCHAIN_FILE="$NDK/build/cmake/android.toolchain.cmake" \\
  -DANDROID_ABI="$ABI" \\
  -DANDROID_PLATFORM="android-$API" \\
  -DANDROID_STL=c++_static \\
  -DCMAKE_BUILD_TYPE=RelWithDebInfo \\
  -DMODKIT_OVERLAY="${MODKIT_OVERLAY:-ON}" \\
  -DMODKIT_HAS_IMGUI="${MODKIT_HAS_IMGUI:-OFF}" \\
  -DMODKIT_HAVE_DOBBY="${MODKIT_HAVE_DOBBY:-OFF}" \\
  "${EXTRA_CMAKE:-}"

cmake --build "$OUT" -j"$(nproc 2>/dev/null || sysctl -n hw.ncpu)"

echo "lib{{lib}}.so -> $OUT/lib{{lib}}.so"
echo "push into the game's data dir, or:  adb install -r app.apk"
"""

README = """# {{app}} — generated offline mod module

Produced by `modkit` from the target's `global-metadata.dat` + `libil2cpp.so`
({{classes}} types / {{methods}} methods indexed, dump source: {{source}}).

| | |
|---|---|
| package | `{{package}}` |
| abi | `{{abi}}` |
| hooked module | `{{so}}` |
| metadata version | {{version}} |
| features | {{nfeat}} |
| instance-capture hooks | {{nhooks}} |

## How it works

1. `modkit` reads the dumper output and turns matched members into a feature table
   (`app/src/main/cpp/features.inc`) with the exact RVAs from the dump.
2. `jni_main.cpp` is loaded inside the game process. It waits for `{{so}}` to be mapped,
   takes the runtime base from `dl_iterate_phdr`, and translates every RVA at that base.
3. Three mechanisms, picked per feature by the analyzer:
   * **const_return** — the method prologue becomes `mov w0/x0, #imm; ret`
     (gold getters, damage, cooldowns). Original bytes are captured before patching,
     so the menu can switch it back off.
   * **value_set / toggle / action** — a direct native call to the managed method with
     the il2cpp ABI (`this` in x0). No patching, nothing to detect.
   * **field_write / static_write** — raw write at `this + off` or at the absolute rva of
     a static field's storage.
4. Instance members need an object. The generator installs a *capture hook* on a
   lifecycle method of the owning class (`Update`, `OnEnable`, …) and caches `this` in a
   slot; the menu shows `obj` / `no obj` next to those entries so you can see when the
   object has not been reached yet.
5. Menu rendering: hook `eglSwapBuffers` → draw ImGui with the game's GL context
   (`overlay.cpp`). With `-DMODKIT_HAS_IMGUI=OFF` the loader activity's console
   (feature key + value) is the fallback UI, which needs no permission at all.

## Build

```sh
# optional but recommended:
git clone --depth 1 https://github.com/ocornut/imgui third_party/imgui
git clone --depth 1 https://github.com/jmp03/Dobby third_party/dobby   # -DMODKIT_HAVE_DOBBY=ON

./build.sh                       # NDK only -> build/arm64-v8a/lib{{lib}}.so
# or  ./gradlew :app:assembleRelease
```

Then load it in the game process: repack the APK with the library in `lib/arm64-v8a/`
plus an `Application` hook that calls `System.loadLibrary("{{lib}}")`, or start it from
the loader app (`LoaderActivity`) for the console build.

## Feature map

| group | feature | kind | target | rva | conf |
|---|---|---|---|---|---|
{{rows}}

## Analyzer notes

{{notes}}

## Verifying on device

```sh
adb logcat -s {{app}} | head -60          # base, hooks, patch sites
adb push modkit.properties /sdcard/Android/data/{{package}}/files/
```

`modkit verify` re-reads the dump and the `.so` and checks every recorded RVA still
points at a plausible function prologue — run it after **any** game update, offsets move
between builds even when the logic does not.

## Limits you should know before wiring the last 10 %

* Only `arm64` encodings are emitted (`movz/movk/ret`, 16-byte patch windows). A 32-bit
  build needs a Thumb-2 encoder; `modkit build --abi armeabi-v7a` will tell you it is
  unsupported instead of emitting garbage.
* Constructors, property accessors with side effects and `System.Void` setters on
  reference-type fields are intentionally not auto-patched — they appear in
  `features.json` with `confidence` < 0.4 and are left out of the table.
* `const_return` on a method whose prologue is PC-relative cannot be inline-hooked with
  the built-in hooker; link Dobby for those.
* Nothing here is obfuscation-proof: if the target renames its symbols, the rules json
  (not the generator) is the place to teach modkit the new names.
"""
